import{_ as e,o as i,c as a,a3 as t}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Objetivo","description":"","frontmatter":{"title":"Objetivo"},"headers":[],"relativePath":"guia/02-objetivo.md","filePath":"guia/02-objetivo.md"}'),r={name:"guia/02-objetivo.md"};function l(n,o,s,c,d,p){return i(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="🎯-2-objetivo" tabindex="-1">🎯 2. Objetivo <a class="header-anchor" href="#🎯-2-objetivo" aria-label="Permalink to &quot;🎯 2. Objetivo&quot;">​</a></h1><p>Este guia, parte integrante do <strong>DomisDocs</strong>, mostra como conectar um projeto <strong>Angular 20 existente</strong> a um projeto já criado no <strong>Firebase</strong> e publicá-lo utilizando o <strong>Firebase Hosting</strong>. O projeto de referência utilizado como exemplo é o <strong>Shadow-Flip-Angular</strong>.</p><p>O processo inclui:</p><ul><li>Instalação do Firebase CLI.</li><li>Autenticação da conta Google.</li><li>Associação do projeto Angular ao projeto Firebase.</li><li>Geração do build de produção.</li><li>Localização do <code>index.html</code> gerado pelo Angular.</li><li>Configuração do Firebase Hosting.</li><li>Configuração de rotas para uma aplicação Single-Page Application.</li><li>Teste local.</li><li>Deploy em produção.</li></ul><p>O Firebase utiliza o arquivo <code>firebase.json</code> para definir o comportamento do Hosting, incluindo a pasta pública, arquivos ignorados, rewrites e redirects.</p><blockquote><p>⚠️ Este tutorial considera uma aplicação Angular client-side/SPA. Projetos com SSR ou arquitetura full-stack podem exigir configuração diferente, incluindo o Firebase App Hosting.</p></blockquote>',6)])])}const b=e(r,[["render",l]]);export{g as __pageData,b as default};
